const d = $json;
const sign = n => (n >= 0 ? '+' : '') + n;
let msg = `📋 *Polybot weekly validation* (${d.strategy_version})\n\n`;
const t = d.trading, e = d.equity;
msg += `*7-day*: ${t.trades} trades · ${t.win_rate}% WR · P&L ${sign(t.pnl)}\n`;
msg += `Break-even ${t.break_even_win_rate}% → margin ${sign(t.margin_pp)}pp\n`;
msg += `Equity $${e.current.toLocaleString()} (${sign(e.change_pct)}% this week)\n\n`;
msg += `*Are our blocks still right?*\n`;
for (const v of (d.forward_validation || [])) {
  const mark = v.verdict === 'block correct' ? '✅' : v.verdict.startsWith('BLOCK') ? '❗' : '➖';
  msg += `${mark} ${v.filter}: ${v.resolved} shadows · ${v.win_rate}% WR · ${sign(v.pnl_per_100)}/$100\n`;
}
if (d.exits.hold_shadow_resolved > 0) {
  msg += `\n*Exit decisions*: ${d.exits.hold_shadow_resolved} measured · `;
  msg += `${d.exits.exits_correct_pct}% correct · net ${sign(d.exits.exit_saved_usd)} → ${d.exits.verdict}`;
}
return [{ json: { text: msg } }];
